import (
	"net"
	"net/http"
	"strconv"
	"sync"
	"time"

	"github.com/novacart/api-gateway/internal/config"
	"github.com/novacart/api-gateway/internal/log"
)

// bucket is a token bucket for one client key.
type bucket struct {
	tokens   float64
	lastSeen time.Time
}

type limiter struct {
	mu      sync.Mutex
	buckets map[string]*bucket
	rps     float64
	burst   float64
}

var shared = func() *limiter {
	cfg, err := config.Load()
	rps := 500
	if err == nil && cfg.RateLimitRPS > 0 {
		rps = cfg.RateLimitRPS
	}
	return &limiter{
		buckets: make(map[string]*bucket),
		rps:     float64(rps),
		burst:   float64(rps) * 1.5,
	}
}()

func clientKey(r *http.Request) string {
	if token := r.Header.Get("X-Api-Client"); token != "" {
		return token
	}
	if host, _, err := net.SplitHostPort(r.RemoteAddr); err == nil {
		return host
	}
	return r.RemoteAddr
}

func (l *limiter) allow(key string) bool {
	now := time.Now()
	l.mu.Lock()
	defer l.mu.Unlock()

	b, ok := l.buckets[key]
	if !ok {
		l.buckets[key] = &bucket{tokens: l.burst - 1, lastSeen: now}
		return true
	}
	b.tokens += now.Sub(b.lastSeen).Seconds() * l.rps
	if b.tokens > l.burst {
		b.tokens = l.burst
	}
	b.lastSeen = now
	if b.tokens < 1 {
		return false
	}
	b.tokens--
	return true
}

// RateLimit rejects callers over their per-client budget with a 429.
func RateLimit(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		key := clientKey(r)
		if !shared.allow(key) {
			log.Warnf("rate limited client=%s path=%s", key, r.URL.Path)
			w.Header().Set("Retry-After", strconv.Itoa(1))
			http.Error(w, "rate limit exceeded", http.StatusTooManyRequests)
			return
		}
		next.ServeHTTP(w, r)
	})
}
